 "Note de saison ≥ {n}": "Season rating ≥ {n}",
 "Ramener un trophée majeur": "Bring home a major trophy",
 "Des écarts d'hygiène de vie répétés se paient sur le terrain.": "Repeated lifestyle slip-ups are being paid for on the pitch.",
 "🅒 Le vestiaire vous confie le brassard de capitaine.": "🅒 The dressing room hands you the captain's armband.",
 "🎽 Première convocation avec les {tier} de {nat}.": "🎽 First call-up to the {nat} {tier} side.",
 "🏆 Sacre en Coupe Nationale : vous voilà qualifié pour une coupe continentale la saison prochaine !": "🏆 National Cup glory: you are through to a continental competition next season!",
 "{name} {year} — le continent à vos pieds.": "{name} {year} — the continent at your feet.",
 "{club2} n'a pas oublié votre prêt réussi : offre de transfert définitif sur la table.": "{club2} have not forgotten your successful loan spell: a permanent bid is on the table.",
 "Votre contrat expire : il faut trancher.": "Your contract is expiring: a decision has to be made.",
 "Vos statistiques n'ont pas convaincu : {club} ne prolonge pas votre contrat. À vous de rebondir ailleurs.": "Your numbers did not convince: {club} are not renewing your contract. Time to bounce back elsewhere.",
 "La montée de {club} fait de vous une cible : rester pour l'aventure, ou viser encore plus haut ?": "{club}'s promotion makes you a target: stay for the adventure, or aim even higher?",
 "La relégation de {club} ouvre votre bon de sortie.": "{club}'s relegation opens your exit door.",
 "Votre temps de jeu famélique alerte tout le marché.": "Your meagre game time has alerted the whole market.",
 "Votre saison XXL affole les recruteurs.": "Your huge season has scouts in a frenzy.",
 "Le club vous a placé sur la liste des transferts : le marché s'organise.": "The club has transfer-listed you: the market is stirring.",
 "Le mercato s'agite autour de votre nom.": "The transfer window is buzzing with your name.",
 "L'élite vous juge trop vieux, mais un gardien chevronné trouve toujours preneur, un ou deux crans plus bas.": "The elite think you are past it, but a seasoned keeper always finds takers a rung or two lower.",
 "Passé 42 ans, plus aucun cador ne mise sur vous : seuls des clubs modestes vous ouvrent encore leurs portes.": "Past 42, no big club will gamble on you: only modest sides still open their doors.",
 "Trop juste pour ce niveau : le club vous remercie. Direction l'échelon inférieur pour vous relancer.": "Not quite up to this level: the club lets you go. Time to drop a division and rebuild.",
 "Le destin ne vous aura pas laissé la moindre chance de rivaliser. {rival} aura eu l'opportunité de construire la carrière qui vous a échappé.": "Fate never gave you the slightest chance to compete. {rival} got to build the career that slipped away from you.",
 "{rival} n'aura même pas eu la chance de faire ses preuves. Le destin vous aura été bien plus favorable qu'à lui.": "{rival} never even got the chance to prove themselves. Fate was far kinder to you.",
 "Vous surpassez très largement {rival} : cette rivalité n'en aura jamais vraiment été une.": "You tower over {rival}: this rivalry was never really one at all.",
 "Vous prenez clairement le dessus sur {rival} au fil des années.": "You clearly got the better of {rival} over the years.",
 "Une rivalité aussi intense que serrée avec {rival} — tout aurait pu basculer à tout moment.": "A rivalry as fierce as it was tight with {rival} — it could have tipped either way at any moment.",
 "{rival} vous aura devancé sur la majeure partie de votre carrière.": "{rival} stayed ahead of you for most of your career.",
 "{rival} aura eu la carrière que vous auriez rêvé d'avoir.": "{rival} had the career you would have dreamed of.",
 "Carrière jamais commencée": "A career that never began",
 "Un diagnostic médical implacable a mis fin à vos espoirs avant même vos débuts professionnels. Une histoire qui aurait pu être si différente.": "An unforgiving medical diagnosis ended your hopes before you ever turned professional. A story that could have been so different.",
 "Carrière écourtée par la blessure": "A career cut short by injury",
 "Une blessure de trop a refermé le rideau plus tôt que vous ne l'auriez voulu. Mais le chemin parcouru, lui, personne ne pourra vous l'enlever.": "One injury too many brought the curtain down sooner than you wanted. But the road you travelled, nobody can take that away.",
 "Carrière fauchée en plein vol": "A career cut down in full flight",
 "En pleine ascension, une blessure implacable a tout arrêté net. On ne saura jamais jusqu'où vous seriez allé — et c'est peut-être ça, le plus cruel.": "On the way up, a merciless injury stopped everything dead. Nobody will ever know how far you would have gone — and perhaps that is the cruellest part.",
 "Carrière brisée": "A broken career",
 "Une blessure sévère a stoppé net votre progression, alors que tout semblait encore possible. Le destin en a décidé autrement.": "A severe injury halted your progress just as everything still seemed possible. Fate decided otherwise.",
 "Star inattendue": "An unexpected star",
 "Rien ne laissait présager un tel sommet, et pourtant vous avez soulevé le plus grand des trophées. Une carrière que personne n'avait vue venir.": "Nothing pointed to such a peak, and yet you lifted the greatest trophy of all. A career nobody saw coming.",
 "Légende du football mondial": "Legend of world football",
 "Votre nom restera gravé parmi les plus grands. Les gamins du monde entier porteront votre maillot pendant des décennies.": "Your name will stay carved among the greatest. Kids the world over will wear your shirt for decades.",
 "Star mondiale": "Global star",
 "Vous avez marqué votre époque et forcé le respect de tout un sport, bien au-delà des frontières de vos clubs.": "You defined your era and earned the respect of an entire sport, far beyond the walls of your clubs.",
 "Joueur de classe internationale": "International-class player",
 "Une carrière remarquable, de celles qui remplissent les stades et les albums de vignettes.": "A remarkable career, the kind that fills stadiums and sticker albums.",
 "Carrière solide et respectée": "A solid, respected career",
 "Sans être une superstar, vous avez mené une carrière dont vous pouvez être fier, reconnue par vos pairs.": "Never a superstar, but a career you can be proud of, recognised by your peers.",
 "Honnête professionnel": "An honest professional",
 "Une carrière sans éclat majeur, mais menée avec sérieux jusqu'au bout, loin des projecteurs.": "A career without great fanfare, but seen through with dedication to the end, far from the spotlight.",
 "Carrière discrète": "A quiet career",
 "Le grand public ne retiendra pas votre nom, mais vous avez vécu de votre passion, et ça n'a pas de prix.": "The wider public will not remember your name, but you made a living from your passion, and that is priceless.",
