 "Génie précoce": "Early Genius",
 "Fêtard": "Party Animal",
 "Une montée en puissance régulière.": "A steady, gradual rise.",
 "Moins de fulgurances, plus de longévité.": "Fewer flashes of brilliance, more longevity.",
 "Un talent qui brûle les étapes dès l'adolescence.": "A talent that skips every step from the teenage years.",
 "Le déclic arrive quand on ne l'attendait plus.": "The penny drops when nobody expected it any more.",
 "Des saisons stratosphériques, d'autres à oublier.": "Some stratospheric seasons, others best forgotten.",
 "Un potentiel immense, un équilibre fragile.": "Immense potential, fragile balance.",
 "Phénoménal à 18 ans… puis le plafond arrive vite.": "Phenomenal at 18… then the ceiling comes fast.",
 "Banal des années, puis une explosion soudaine.": "Ordinary for years, then a sudden explosion.",
 "Progression classique": "Standard progression",
 "Lente mais sûre": "Slow but sure",
 "Explosion précoce": "Early explosion",
 "Révélation tardive": "Late bloomer",
 "Montagnes russes": "Rollercoaster",
 "Diamant instable": "Unstable diamond",
 "Météore": "Meteor",
 "Déclic fulgurant": "Sudden spark",
 "Élimination en poules": "Group stage exit",
 "Huitième de finale": "Round of 16",
 "Quart de finale": "Quarter-final",
 "Demi-finale": "Semi-final",
 "Finaliste": "Runner-up",
 "La désillusion : votre nation sort dès les poules, dans un silence de cathédrale.": "Bitter disappointment: your nation goes out in the group stage, in deathly silence.",
 "L'aventure s'arrête en huitièmes, au terme d'un match à suspense.": "The run ends in the last 16, at the end of a nail-biter.",
 "Un quart de finale héroïque, perdu au bout de la nuit. La fierté domine.": "A heroic quarter-final, lost deep into the night. Pride wins out.",
 "Si proche du rêve : la demi-finale se referme cruellement.": "So close to the dream: the semi-final slams shut, cruelly.",
 "Finale perdue. La deuxième plus belle équipe du monde, et le plus grand des vides.": "Final lost. The second-best team in the world, and the emptiest feeling of all.",
 "AU BOUT DE LA NUIT ! Votre nation est sur le toit du monde, et vous au cœur de la légende !": "DEEP INTO THE NIGHT! Your nation is on top of the world, and you're at the heart of the legend!",
 "Atteindre 85 de général avant 23 ans.": "Reach 85 OVR before turning 23.",
 "Décrocher le trait Leader né ET un titre de champion.": "Earn the Born Leader trait AND a league title.",
 "Partir d'un club régional et gagner un titre de première division.": "Start at a regional club and win a first-division title.",
 "Signer dans le Golfe (Arabie Saoudite, Qatar ou Émirats) après 33 ans.": "Sign in the Gulf (Saudi Arabia, Qatar or the Emirates) after 33.",
 "Remporter 2 Ballons d'Or dans une même carrière.": "Win 2 Ballons d'Or in a single career.",
 "Porter les couleurs d'au moins 5 clubs différents.": "Wear the colours of at least 5 different clubs.",
 "Marquer 400 buts en carrière.": "Score 400 career goals.",
 "La carrière du prodige": "The prodigy's career",
 "Le patron du vestiaire": "The dressing-room boss",
 "La remontada": "The remontada",
 "Le dernier contrat": "The last contract",
 "La dynastie": "The dynasty",
